ST.xhtml:p:
RTrigger(CLK := g_bZRelExecuteM OR bRelEXecute OR g_bZRelExecute);
FTrigger(CLK :=  bRelEXecute OR g_bZRelExecute);
RTrigger0(CLK := g_bZRelCloseM);
RTrigger1(CLK := g_bAxisStopFlag);
RTrigger2(CLK := g_bAxisStopFlag_1);

IF RTrigger.Q THEN
  g_boZRelDone := FALSE;
  g_bZRelDone := FALSE;
  bRelDone := FALSE;

  IF g_bZRelExecuteM THEN
    g_bZRelExecuteM := FALSE;
    nRelState := 1;
    dTargetPos := Axis_Z.NCTOPLC.ActPos + g_fZRelDistanceM;
    dTargetVel := g_fZRelVelocityM;


    IF g_bSetAuxiliaryAxisSpeed THEN
      dTargetVel := g_nAuxiliaryAxisSpeed;
      g_bSetAuxiliaryAxisSpeed := FALSE;
    END_IF;

  ELSIF g_bZRelExecute THEN
    nRelState := 2;
    dTargetPos := Axis_Z.NCTOPLC.ActPos + g_fZRelDistance; 
    dTargetVel := g_fZRelVelocity;

  ELSE
    nRelState := 30;
    dTargetPos := Axis_Z.NCTOPLC.ActPos + dRelDistance; 
    IF g_bFastInch=0 THEN
      dTargetVel := dZAxisSlowVel;
    ELSE
      dTargetVel := dZAxisFastVel;
    END_IF;
	bRelEXecute := FALSE;
  END_IF;
  IF dTargetVel = 0.0 THEN
    dTargetVel := g_fZAxisVel;
  END_IF;
  (*向上运动超过了最高点只能到最高点*)
    IF dTargetPos > g_fLiftCoord THEN
      dTargetPos := g_fLiftCoord;
    END_IF;

    (*向下运动如果你开启了软限位就只能到负软限位+0.5的位置*)
    IF g_bZAxisIsOpenSoftWareLimit AND dTargetPos <= g_dZAxisNegSoftWareValue THEN
          dTargetPos := g_dZAxisNegSoftWareValue + 0.5;
    END_IF;
  bRelClose := FALSE;
END_IF;

IF FTrigger.Q OR RTrigger0.Q THEN
  bRelClose := TRUE;
  g_bZRelCloseM := FALSE;
END_IF;
IF bRelClose THEN 
  g_boZRelDone := FALSE;
  g_bZRelDone := FALSE;
  bRelDone := FALSE;
  M.ENABLE[165] := 0;
  bRelClose := FALSE;
END_IF;

IF RTrigger1.Q THEN
  IF g_nAxisStopP = 1 THEN
    g_bAxisStopFlag :=FALSE;
    nRelState := 21;
  END_IF;
END_IF;

IF RTrigger2.Q THEN
  IF g_bAxisStopFlag_1 THEN
    g_bAxisStopFlag_1 :=FALSE;
    nRelState := 21;
  END_IF;
END_IF;

CASE nRelState OF
  0:
    nRelState := 0;
  1:
    g_ZMoveRel.Execute := TRUE;
    g_ZMoveRel.Velocity := dTargetVel;
    g_ZMoveRel.Distance := dTargetPos - Axis_Z.NCTOPLC.ActPos;
    IF g_ZMoveRel.Done THEN
      g_ZMoveRel.Execute := FALSE;
      g_boZRelDone := TRUE;
      g_bZRelDone := TRUE;
      bRelDone := TRUE;
      nRelState := 0;
      g_bZAxisMoveDoneM320 := TRUE;
	  g_bExecuteFinishedM164 := FALSE;
      M.ENABLE[164] := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nRelState := 20;
    END_IF;
    IF g_ZMoveRel.CommandAborted OR g_ZMoveRel.Error THEN
      IF g_ZMoveRel.CommandAborted THEN
		g_nZErrorIDToHmi := BOOL_TO_INT(g_ZMoveRel.CommandAborted) + 1001;
      ELSE
        g_nZErrorIDToHmi := USINT_TO_INT(g_ZMoveRel.ErrorId);  
      END_IF;  
      g_nFollowStateToHmi := g_nFollowState;
      g_ZMoveRel.Execute := FALSE;
      nRelState := 0;
    END_IF;
  2:
    g_ZMoveRel.Execute := TRUE;
    g_ZMoveRel.Velocity := dTargetVel;
    g_ZMoveRel.Distance := dTargetPos - Axis_Z.NCTOPLC.ActPos;
    IF g_ZMoveRel.Done THEN
      g_ZMoveRel.Execute := FALSE;
      g_boZRelDone := TRUE;
      g_bZRelDone := TRUE;
      bRelDone := TRUE;
      nRelState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nRelState := 21;
    END_IF;
    IF g_ZMoveRel.CommandAborted OR g_ZMoveRel.Error THEN
      IF g_ZMoveRel.CommandAborted THEN
		g_nZErrorIDToHmi := BOOL_TO_INT(g_ZMoveRel.CommandAborted) + 1001;
      ELSE
        g_nZErrorIDToHmi := USINT_TO_INT(g_ZMoveRel.ErrorId);  
      END_IF;  
      g_nFollowStateToHmi := g_nFollowState;
      g_ZMoveRel.Execute := FALSE;
      nRelState := 0;
    END_IF;
  20:
    g_ZMoveRel.Execute := FALSE;
    g_ZMoveStop.Execute := TRUE;
    IF g_ZMoveStop.Done AND g_bPlcStartBuffer THEN
      g_ZMoveStop.Execute := FALSE;
      nRelState := 1;
    END_IF;
    IF g_ZMoveStop.CommandAborted OR g_ZMoveStop.Error THEN
      g_ZMoveStop.Execute := FALSE;
      nRelState := 0;
    END_IF;
  21:
    g_ZMoveRel.Execute := FALSE;
    g_ZMoveStop.Execute := TRUE;
    IF g_ZMoveStop.Done THEN
      g_bFinishedM325_1 := FALSE;
      M.ENABLE[325] := 0;
      g_ZMoveStop.Execute := FALSE;
      nRelState := 0;
    END_IF;
    IF g_ZMoveStop.CommandAborted OR g_ZMoveStop.Error THEN
      g_ZMoveStop.Execute := FALSE;
      g_bFinishedM325_1 := FALSE;
      M.ENABLE[325] := 0;
      nRelState := 0;
    END_IF;
  30:
    IF Axis_Z.NCTOPLC.AxisState = 9 THEN
      nRelState := 31;
    ELSE

      nRelState := 1;
    END_IF;
  31:
    g_ZMoveStop.Execute := TRUE;
    IF g_ZMoveStop.Done THEN
      g_ZMoveStop.Execute := FALSE;
      nRelState := 1;
    END_IF;
    IF g_ZMoveStop.CommandAborted OR g_ZMoveStop.Error THEN
      g_ZMoveStop.Execute := FALSE;
      nRelState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nRelState := 0;
  g_ZMoveRel.Execute := FALSE;
  g_ZMoveStop.Execute := FALSE;
  g_bFinishedM325_1 := FALSE;
END_IF;
